async function searchPlaces(q){const country=document.querySelector('#country').value.trim(),saved=customPlaces().filter(x=>(!country||x.country.toLowerCase()===country.toLowerCase())&&x.label.toLowerCase().includes(q.toLowerCase()));placeHints.replaceChildren();saved.forEach(x=>addPlaceOption(x,true));try{if(placeAbort)placeAbort.abort();placeAbort=new AbortController();const query=`${q} ${country}`.trim(),res=await fetch(`https://photon.komoot.io/api/?limit=9&lang=en&q=${encodeURIComponent(query)}`,{signal:placeAbort.signal});if(!res.ok)throw new Error('search unavailable');const json=await res.json(),items=(json.features||[]).filter(x=>x.geometry?.coordinates&&(!country||String(x.properties?.country||'').toLowerCase()===country.toLowerCase()));items.forEach(item=>{const p=item.properties||{},parts=[p.name,p.city||p.district,p.state,p.country].filter((v,i,a)=>v&&a.indexOf(v)===i);addPlaceOption({label:parts.join(', '),lat:item.geometry.coordinates[1],lon:item.geometry.coordinates[0],country:p.country})});const total=saved.length+items.length;placeHints.hidden=!total;placeStatus.textContent=total?`${total} matching place${total===1?'':'s'} found in ${country||'the world'}`:'No match found — enter coordinates and save this place';}catch(e){if(e.name!=='AbortError'){placeHints.hidden=!saved.length;placeStatus.textContent=saved.length?`${saved.length} saved place${saved.length===1?'':'s'} found`:'Online search unavailable — add the place manually';}}}
