document.querySelector('#sameAsBirthBtn').onclick=copyBirthToResidence;
currentPlaceInput.addEventListener('input',()=>{clearTimeout(currentPlaceTimer);const q=currentPlaceInput.value.trim();if(q.length<3){currentPlaceHints.hidden=true;currentPlaceStatus.textContent='Type at least 3 letters, or leave blank to use birth place';return}currentPlaceStatus.textContent='Searching current residence…';currentPlaceTimer=setTimeout(()=>searchCurrentPlaces(q),350)});
async function searchCurrentPlaces(q){const country=document.querySelector('#currentCountry').value.trim();currentPlaceHints.replaceChildren();try{if(currentPlaceAbort)currentPlaceAbort.abort();currentPlaceAbort=new AbortController();const res=await fetch(`https://photon.komoot.io/api/?limit=9&lang=en&q=${encodeURIComponent(`${q} ${country}`.trim())}`,{signal:currentPlaceAbort.signal});if(!res.ok)throw new Error();const json=await res.json(),items=(json.features||[]).filter(x=>x.geometry?.coordinates&&(!country||String(x.properties?.country||'').toLowerCase()===country.toLowerCase()));items.forEach(item=>{const p=item.properties||{},parts=[p.name,p.city||p.district,p.state,p.country].filter((v,i,a)=>v&&a.indexOf(v)===i),button=document.createElement('button');button.type='button';button.className='place-option';button.innerHTML=`<strong>${parts[0]||'Place'}</strong><small>${parts.slice(1).join(', ')}</small>`;button.onclick=()=>selectCurrentPlace(parts.join(', '),item.geometry.coordinates[1],item.geometry.coordinates[0],p.country);currentPlaceHints.appendChild(button)});currentPlaceHints.hidden=!items.length;currentPlaceStatus.textContent=items.length?`${items.length} residence suggestions found`:'No matching residence found; coordinates may be entered manually';}catch(e){if(e.name!=='AbortError')currentPlaceStatus.textContent='Residence search needs internet; enter coordinates manually';}}
async function selectCurrentPlace(label,lat,lon,country){currentPlaceInput.value=label;if(country)document.querySelector('#currentCountry').value=country;document.querySelector('#currentLat').value=Number(lat).toFixed(4);document.querySelector('#currentLon').value=Number(lon).toFixed(4);currentPlaceHints.hidden=true;currentPlaceStatus.textContent='Residence coordinates inserted · detecting time zone…';try{const r=await fetch(`https://timeapi.io/api/timezone/coordinate?latitude=${lat}&longitude=${lon}`);if(!r.ok)throw new Error();const z=await r.json(),seconds=z.currentUtcOffset?.seconds??z.currentUtcOffsetSeconds;let offset=seconds!=null?Number(seconds)/3600:null;if(offset==null&&z.currentUtcOffset?.hours!=null)offset=Number(z.currentUtcOffset.hours)+(Number(z.currentUtcOffset.minutes)||0)/60;if(Number.isFinite(offset))document.querySelector('#currentTimezone').value=offset;document.querySelector('#currentTimezoneName').textContent=z.timeZone||z.timeZoneId||z.zoneName||'Residence time zone';currentPlaceStatus.textContent='Current residence will now affect predictions';}catch(e){currentPlaceStatus.textContent='Coordinates inserted; verify current UTC offset';}}
function isPaidActivated(){return window.KUNDALI_GOOGLE_PLAY_PAID===true||window.HIRAK_ACTIVATED===true}
document.querySelector('#forecastStart').value=new Date().toISOString().slice(0,10);
document.querySelector('#updateBtn').onclick=()=>alert('Manual Update Center\n\nHirak Jyotish Chakra 3.0 Licensed Edition is installed.\n\nFor updates contact Hirak Chatterjee:\nPhone: 9830431246\nWhatsApp: 9830961246\nEmail: hirakhkc@gmail.com\n\nUpdates remain manual for safety.');
fetch('https://restcountries.com/v3.1/all?fields=name').then(r=>r.json()).then(items=>{const list=document.querySelector('#countryList');items.map(x=>x.name?.common).filter(Boolean).sort().forEach(name=>{const o=document.createElement('option');o.value=name;list.appendChild(o)})}).catch(()=>{});
const softwareShell=document.querySelector('#softwareShell');
if(isPaidActivated()){softwareShell.hidden=false;render(getData())}
